const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const sierraEstrella = ee.Geometry.Point([-112.38, 33.35]); // Sierra Estrella approximate center
  const phxAirport = ee.Geometry.Point([-112.01, 33.43]); // Phoenix Sky Harbor Airport

  // 2. Date range
  const startDate = '2023-07-19';
  const endDate = '2023-07-20';

  // 3. Load MODIS Terra LST collection
  let col = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(sierraEstrella.union(phxAirport));

  const colSize = col.size().getInfo();
  console.log(`MODIS images found: ${colSize}`);

  if (colSize === 0) {
    console.log('No MODIS data available, trying Landsat 9...');
    col = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate('2023-07-15', '2023-07-25')
      .filterBounds(sierraEstrella.union(phxAirport));

    const landsat9Size = col.size().getInfo();
    console.log(`Landsat 9 images found: ${landsat9Size}`);

    if (landsat9Size === 0) {
      console.log('No images found for the date and location.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Process MODIS LST (if available)
  if (colSize > 0) {
    const img = col.first();

    // LST_Day_1km band in Kelvin * 0.02 scale factor
    const lstDay = img.select('LST_Day_1km').multiply(0.02);

    // Apply QA mask (bits 0-1 must be 0 for good quality)
    const qc = img.select('QC_Day');
    const mask = qc.bitwiseAnd(3).eq(0);
    const lstMasked = lstDay.updateMask(mask);

    // 5. Calculate mean LST for Sierra Estrella
    const sierraStats = lstMasked.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: sierraEstrella.buffer(5000),
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const sierraLST = sierraStats['LST_Day_1km_mean'];
    const sierraCount = sierraStats['LST_Day_1km_count'];

    // 6. Calculate mean LST for PHX Airport
    const phxStats = lstMasked.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: phxAirport.buffer(5000),
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const phxLST = phxStats['LST_Day_1km_mean'];
    const phxCount = phxStats['LST_Day_1km_count'];

    console.log(`Sierra Estrella - LST: ${sierraLST ? sierraLST.toFixed(2) : 'null'} K, Pixels: ${sierraCount || 0}`);
    console.log(`PHX Airport - LST: ${phxLST ? phxLST.toFixed(2) : 'null'} K, Pixels: ${phxCount || 0}`);

    // 7. Validation and final answer
    if (sierraCount === 0 || phxCount === 0) {
      console.log('No valid pixels after QA masking.');
      console.log('<answer>C2</answer>');
      return;
    }

    if (sierraLST === null || sierraLST === undefined || phxLST === null || phxLST === undefined) {
      console.log('LST calculation returned null.');
      console.log('<answer>C3</answer>');
      return;
    }

    if (sierraLST < 250 || sierraLST > 350 || phxLST < 250 || phxLST > 350) {
      console.log('LST values out of reasonable range.');
      console.log('<answer>C3</answer>');
      return;
    }

    if (sierraLST > phxLST) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
